const $=id=>document.getElementById(id);const notice=s=>$('notice').textContent=s;
const pages={requests:['admin.html','Demandes'],crm:['crm.html','CRM'],quotes:['quotes.html','Devis'],tenders:['tenders.html','Appels d’offres'],consultants:['consultants.html','Consultants'],recruitment:['recruitment.html','Recrutement'],missions:['missions.html','Missions'],billing:['billing.html','Finance'],direction:['direction.html','Direction'],accounts:['accounts.html','Comptes'],audit:['audit.html','Journal'],documents:['documents.html','Documents privés'],alerts:['alerts.html','Alertes métier'],notifications:['notifications.html','Notifications'],'my-activity':['my-activity.html','Mes CRA']};
async function api(action,data){const r=await fetch('/api/auth/'+action,{method:data?'POST':'GET',headers:{'Content-Type':'application/json',Authorization:'Bearer session','X-DSIG-Session':'cookie'},...(data?{body:JSON.stringify(data)}:{})});const d=await r.json();if(!r.ok)throw Error(d.error);return d}
function show(d){$('role').textContent=d.role;$('modules').replaceChildren();for(const [resource,[url,label]] of Object.entries(pages)){const mode=d.permissions[resource]??d.permissions['*'];if(!mode)continue;const a=document.createElement('a');a.className='count';a.href=url;const name=document.createElement('span'),access=document.createElement('span');name.className='module-name';name.textContent=label;access.className='module-mode';access.textContent=mode.includes('W')?'Lecture / écriture':'Lecture';a.append(name,access);$('modules').append(a);if(resource==='crm'){const agenda=a.cloneNode(true);agenda.href='appointments.html';agenda.querySelector('.module-name').textContent='Rendez-vous commerciaux';$('modules').append(agenda)}}$('workspace').hidden=false;$('login').hidden=true;notice(d.mfa_required&&!d.mfa_enabled?'Activation MFA obligatoire avant accès aux modules.':'Connecté.')}
function reset(){$('workspace').hidden=true;$('login').hidden=false;$('secret').value='';$('mfa-pending').hidden=true;$('modules').replaceChildren()}
for(const [id,action] of [['activate','activate'],['signin','login'],['mfa-setup','mfa-setup'],['mfa-confirm','mfa-confirm']])$(id).onsubmit=async e=>{e.preventDefault();const b=e.submitter;b.disabled=true;try{const d=await api(action,Object.fromEntries(new FormData(e.target)));e.target.reset();if(action==='activate')notice('Activation effectuée. Connectez-vous.');else if(action==='login')show(d);else if(action==='mfa-setup'){$('secret').value=d.secret;$('mfa-pending').hidden=false;notice('Configurez puis confirmez le code.')}else{reset();$('recovery-codes').textContent=d.recovery_codes.join('\n');$('recovery').hidden=false;notice('MFA activée. Conservez vos codes de secours avant de vous reconnecter.')}}catch(err){notice(err.message)}finally{b.disabled=false}};
$('dismiss-recovery').onclick=()=>{$('recovery-codes').textContent='';$('recovery').hidden=true};
$('logout').onclick=async()=>{try{await api('logout',{});reset();notice('Session révoquée.')}catch(e){notice(e.message)}};
async function refreshSecurity(){const d=await api('me');$('session-status').textContent=`${d.active_sessions} session(s) active(s)`;$('mfa-status').textContent=d.mfa_enabled?'MFA activée':d.mfa_required?'MFA obligatoire — activation nécessaire':'MFA non activée';$('mfa-setup').hidden=d.mfa_enabled;}
$('revoke-others').onsubmit=async e=>{e.preventDefault();const b=e.submitter;b.disabled=true;try{const d=await api('revoke-others',Object.fromEntries(new FormData(e.target)));await refreshSecurity();notice(`${d.revoked} session(s) révoquée(s).`)}catch(err){notice(err.message)}finally{e.target.reset();b.disabled=false}};
const originalShow=show;show=d=>{originalShow(d);refreshSecurity().catch(err=>notice(err.message))};api('me').then(show).catch(()=>{});

